#pragma once
#include <array>
#include <cstdint>
namespace ks {
class StateStorageTask final {
public:enum class Kind {BindCurrent,BindPart,MultiAddress,Dirty,NameTables,Tables};enum class Stage {ReadMode,AdmitMode,ReadPart,BindPartChild,ReturnCurrent,NormalizePart,SetPartStride,ScalePart,CopyPartOffset,AddCurrentBase,WriteCurrentBase,AddLiveBase,WriteLiveBase,ReturnPart,ReadBank,NormalizeBank,SetBankStride,ScaleBank,AddMultiBase,ReturnMulti,ReadDirty,ReadDirtyPart,SetDirty,WriteDirty,ReturnDirty,SetNameFieldTable,WriteNameFieldTable,SetNameLimitTable,WriteNameLimitTable,SetNameDisplayTable,WriteNameDisplayTable,ReturnNameTables,SetFieldTable,WriteFieldTable,SetLimitTable,WriteLimitTable,SetDisplayTable,WriteDisplayTable,ReturnTables,AwaitPart,Complete};enum class Read {Mode,Part,Bank,Dirty,DirtyPart};enum class Write {CurrentBase,LiveBase,Dirty,FieldTable,LimitTable,DisplayTable};
 StateStorageTask(Kind k,uint8_t part=0):kind_(k),phase_(k==Kind::BindCurrent?Stage::ReadMode:k==Kind::BindPart?Stage::NormalizePart:k==Kind::MultiAddress?Stage::ReadBank:k==Kind::Dirty?Stage::ReadDirty:k==Kind::NameTables?Stage::SetNameFieldTable:Stage::SetFieldTable),part_(part){}
 Kind kind()const{return kind_;}Stage stage()const{return phase_;}bool complete()const{return phase_==Stage::Complete;}bool awaitingPart()const{return phase_==Stage::AwaitPart;}bool resumePart(){if(!awaitingPart())return false;phase_=Stage::ReturnCurrent;return true;}uint8_t part()const{return part_;}uint32_t address()const{return address_;}
 unsigned nextClocks()const{constexpr std::array<unsigned,39> c{{12,3,12,20,17,3,6,23,3,9,18,9,18,17,12,3,6,23,9,17,12,12,3,12,17,9,18,9,18,9,18,17,9,18,9,18,9,18,17}};return unsigned(phase_)<c.size()?c[unsigned(phase_)]:0;}
 template<class Reader,class Writer>unsigned advanceBefore(unsigned available,Reader&& read,Writer&& write){unsigned used=0;while(const auto cost=nextClocks()){if(cost>available-used)break;switch(phase_){case Stage::ReadMode:mode_=uint8_t(read(Read::Mode));next();break;case Stage::AdmitMode:phase_=mode_?Stage::ReadPart:Stage::ReturnCurrent;break;case Stage::ReadPart:part_=uint8_t(read(Read::Part));next();break;case Stage::BindPartChild:phase_=Stage::AwaitPart;break;
 case Stage::ScalePart:address_=uint32_t(part_)*256;next();break;case Stage::AddCurrentBase:address_+=0x168fc;next();break;case Stage::WriteCurrentBase:write(Write::CurrentBase,address_);next();break;case Stage::AddLiveBase:live_=uint32_t(part_)*256+0x16e12;next();break;case Stage::WriteLiveBase:write(Write::LiveBase,live_);next();break;
 case Stage::ReadBank:bank_=uint8_t(read(Read::Bank));next();break;case Stage::ScaleBank:address_=uint32_t(bank_)*1024;next();break;case Stage::AddMultiBase:address_+=0x845800;next();break;
 case Stage::ReadDirty:dirty_=uint8_t(read(Read::Dirty));next();break;case Stage::ReadDirtyPart:part_=uint8_t(read(Read::DirtyPart));next();break;case Stage::SetDirty:dirty_|=uint8_t(1u<<(part_&7));next();break;case Stage::WriteDirty:write(Write::Dirty,dirty_);next();break;
 case Stage::WriteNameFieldTable:write(Write::FieldTable,0x11210);next();break;case Stage::WriteNameLimitTable:write(Write::LimitTable,0x112db);next();break;case Stage::WriteNameDisplayTable:write(Write::DisplayTable,0x1142c);next();break;
 case Stage::WriteFieldTable:write(Write::FieldTable,0x11143);next();break;case Stage::WriteLimitTable:write(Write::LimitTable,0x11299);next();break;case Stage::WriteDisplayTable:write(Write::DisplayTable,0x1141f);next();break;
 case Stage::ReturnCurrent:case Stage::ReturnPart:case Stage::ReturnMulti:case Stage::ReturnDirty:case Stage::ReturnNameTables:case Stage::ReturnTables:phase_=Stage::Complete;break;default:next();break;}used+=cost;}return used;}
private:void next(){phase_=Stage(unsigned(phase_)+1);}Kind kind_;Stage phase_;uint8_t part_=0,mode_=0,bank_=0,dirty_=0;uint32_t address_=0,live_=0;
};}
